   /**
    * Creates the provided command.
    * 
    * @param		command ${class.getCreateCommandAlias()}
    * @exception    ProcessingException
    * @exception	IllegalArgumentException
    * @return		Anomaly
    */
	public Anomaly createAnomaly( CreateAnomalyCommand command )
    throws ProcessingException, IllegalArgumentException {

		Anomaly entity = new Anomaly();

		try {
			// --------------------------------------
        	// validate the command
        	// --------------------------------------    	
        	AnomalyValidator.getInstance().validate( command );    

            entity.setAnomalyId( command.getAnomalyId() );
            entity.setOccurredAt( command.getOccurredAt() );
            entity.setDetails( command.getDetails() );
            entity.setAnomalyType( command.getAnomalyType() );
            entity.setSeverity( command.getSeverity() );
    	    
        	// ------------------------------------------
        	// persist a new one
        	// ------------------------------------------ 
    	    entity = projector.create(entity);
    	    
			LOGGER.log( Level.INFO, "done creating of Anomaly {0} ", entity.toString() );
			
        }
        catch (Exception exc) {
            final String errMsg = "Unable to create Anomaly - " + exc;
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }

   /**
    * Update the provided command.
    * @param		command UpdateAnomalyCommand
    * @exception    ProcessingException
    * @exception  	IllegalArgumentException
    * @return		Anomaly
    */
    public Anomaly updateAnomaly( UpdateAnomalyCommand command ) 
    throws ProcessingException, IllegalArgumentException {

	    Anomaly entity = new Anomaly();

    	try {       

			// --------------------------------------
        	// validate 
        	// --------------------------------------    	
        	AnomalyValidator.getInstance().validate( command );    

            entity.setAnomalyId( command.getAnomalyId() );
            entity.setOccurredAt( command.getOccurredAt() );
            entity.setDetails( command.getDetails() );
            entity.setTimeSeries( command.getTimeSeries() );
            entity.setAlert( command.getAlert() );
            entity.setDataset( command.getDataset() );
            entity.setAnomalyType( command.getAnomalyType() );
            entity.setSeverity( command.getSeverity() );
        	
        	// ------------------------------------------
        	// persist an existing one
        	// ------------------------------------------ 
        	entity = projector.update(entity);
    	    
			LOGGER.log( Level.INFO, "done saving of Anomaly {0} ", entity.toString() );
    	}
        catch (Exception exc) {
            final String errMsg = "Unable to save Anomaly - " + exc;
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
    	
    	return entity;
    }
   
   /**
    * Deletes the associatied value object
    * @param		command DeleteAnomalyCommand
    * @exception 	ProcessingException
    */
    public void delete( DeleteAnomalyCommand command ) 
    throws ProcessingException, IllegalArgumentException {	
        UUID id = null;
        
    	try {  
			// --------------------------------------
        	// validate the command
        	// --------------------------------------    	
        	AnomalyValidator.getInstance().validate( command );    
        
        	id = command.getAnomalyId();
        	
        	// ------------------------------------------
        	// delete the entity
        	// ------------------------------------------
        	projector.delete(id);

        	LOGGER.log( Level.INFO, "done deleting of Anomaly {0} ", id );

        }
        catch (Exception exc) {
            final String errMsg = "Unable to delete Anomaly using Id = "  + id;
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }
    }

    /**
     * Method to retrieve the Anomaly via AnomalyFetchOneSummary
     * @param 	summary AnomalyFetchOneSummary 
     * @return 	AnomalyFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Anomaly getAnomaly( AnomalyFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "AnomalyFetchOneSummary arg cannot be null" );
    	
    	Anomaly entity = null;
    	UUID id = summary.getAnomalyId();
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	AnomalyValidator.getInstance().validate( summary );    
        	
        	// --------------------------------------
        	// find a Anomaly using the provided id
        	// --------------------------------------
        	entity = projector.find( id );
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Anomaly with id " + id;
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


    /**
     * Method to retrieve a collection of all Anomalys
     *
     * @return 	List<Anomaly> 
     * @exception ProcessingException Thrown if any problems
     */
    public List<Anomaly> getAllAnomaly() 
    throws ProcessingException {
        List<Anomaly> list = null;

        try {        	
        	list = projector.findAll( new FindAllAnomalyQuery() );
        }
        catch( Exception exc ) {
            String errMsg = "Failed to get all Anomaly";
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return list;
    }

    /**
     * assign TimeSeries on Anomaly
     * @param		command AssignTimeSeriesToAnomalyCommand	
     * @exception	ProcessingException
     */     
	public void assignTimeSeries( AssignTimeSeriesToAnomalyCommand command ) throws ProcessingException {

		try {
			// --------------------------------------
	    	// best to validate the command now
	    	// --------------------------------------    
	    	AnomalyValidator.getInstance().validate( command );    

			// --------------------------------------
	    	// delegate to the projector
	    	// --------------------------------------    	    	
	    	projector.assignTimeSeries(command.getAnomalyId(), command.getAssignment());
		    
		}
        catch( Throwable exc ) {
			final String msg = "Failed to get TimeSeries using id " + command.getAnomalyId();
			LOGGER.log( Level.WARNING,  msg );
			throw new ProcessingException( msg, exc );
        }
	}

